import{_ as s,l as o,o as e,c as i,v as n,p as l,x as t,d as h,i as T,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"常见和式与递推","description":"","frontmatter":{"title":"常见和式与递推","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sum-recurrence.md","filePath":"cs/sum-recurrence.md","lastUpdated":1789023840000}'),d={name:"cs/sum-recurrence.md"};function p(m,a,u,_,E,f){const r=o("Mermaid");return e(),i("div",null,[a[1]||(a[1]=n('<h1 id="常见和式与递推" tabindex="-1">常见和式与递推 <a class="header-anchor" href="#常见和式与递推" aria-label="Permalink to &quot;常见和式与递推&quot;">​</a></h1><div class="epigraph"><p>$T(n)=T(n-1)+n$ 展开就是三角数；几何和与调和和决定了后课循环代价是平方、指数还是对数。</p><footer>—— 据 Rosen, Discrete Mathematics and Its Applications；Cormen, Leiserson, Rivest and Stein 整理</footer></div><p>上一课<a href="/cs/asymptotic-notation">渐近记号</a>钉死了 \\(O\\)、\\(\\Omega\\)、\\(\\Theta\\) 比较增长，当时假定 \\(T(n)\\) 已经是闭式或已知阶。本课不重定义 \\(n_0\\) 与 \\(c\\)，也不从主定理另起——主定理是算法课分治叶子。缺口是：循环与简单递归给出的是<strong>和式或递推</strong>，还不是闭式。没有求和，记号没有对象。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一层循环加到 \\(n\\) 是 \\(\\sum_{k=1}^n 1=\\Theta(n)\\)。嵌套或 \\(T(n)=T(n-1)+n\\)、\\(T(0)=0\\) 展开为 \\(\\sum k=\\Theta(n^2)\\)。缺口因此不是新的 \\(O\\) 定义，而是几张表：等差 \\(\\sum k=n(n+1)/2\\)，等比 \\(\\sum r^k\\) 在 \\(|r|\\lt 1\\) 时有界、\\(r=2\\) 时 \\(\\Theta(2^n)\\)，调和数 \\(H_n=\\sum_{k=1}^n 1/k=\\Theta(\\log n)\\)。展开线性递推 \\(T(n)=T(n-1)+f(n)\\) 得 \\(T(n)=T(0)+\\sum f\\)。</p><p>分治 \\(T(n)=2T(n/2)+n\\) 只点到「展开成 \\(\\Theta(n\\log n)\\)」，证明留给后课主定理。本课够用的是减一递推与有限和。</p><h3 id="不是求和过程" tabindex="-1">\\(\\Theta\\) 不是求和过程 <a class="header-anchor" href="#不是求和过程" aria-label="Permalink to &quot;$\\Theta$ 不是求和过程&quot;">​</a></h3><p>先求和或展开，再对闭式套上一课的记号。把「循环两层」直接写成 \\(O(n^2)\\) 可以当口诀，但 \\(f(n)\\) 若是 \\(2^n\\)，层数不再给出多项式。本课要求能认出和式形状。</p><p><span class="marginnote">Rosen 给出求和公式与递推求解。CLRS 在渐近章之后用求和估计循环。调和和出现在哈希与树的平均高度直觉里，严格期望要等概率课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>算术和、几何和按闭式。调和和用积分夹逼得到 \\(\\Theta(\\log n)\\)，本课不把 Euler 常数当必考。递推：反复代入直到 \\(T(0)\\)，再对和式套 \\(\\Theta\\)。归纳可验证猜出的闭式——<a href="/cs/mathematical-induction">数学归纳</a>的格式在此当检验，不代替展开。</p>',11)),(e(),l(c,null,{default:t(()=>[T(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ASYM%5B%22O%20%2F%20%CE%98%20%E8%AE%B0%E5%8F%B7%22%5D%20--%3E%20SUM%5B%22%E5%92%8C%E5%BC%8F%E9%97%AD%E5%BC%8F%22%5D%0A%20%20SUM%20--%3E%20REC%5B%22T(n)%3DT(n-1)%2Bf(n)%22%5D%0A%20%20REC%20--%3E%20T%5B%22T%20%E7%9A%84%E9%98%B6%22%5D%0A%20%20T%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AT%20%E4%BD%9C%E7%94%A8%E5%9C%A8%E5%9B%BE%E4%B8%8A%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=n('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>后课邻接表扫描是 \\(\\Theta(V+E)\\)，来自「每边、每点常数次」的和，不是新记号。树高最坏 \\(\\Theta(n)\\)、平衡后 \\(\\Theta(\\log n)\\)，对数来自反复减半或调和型代价。本课先把和与减一递推钉死，图的 \\(|V|\\)、\\(|E|\\) 下一课才成为参数。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入生成函数解线性递推的一般理论，不证主定理全部情形。摊还分析是后课数据结构叶子。连续积分只当夹逼工具。</p><p>后课默认：循环代价先写成和或减一递推，再收成 \\(\\Theta\\)；图算法的 \\(T\\) 用 \\(|V|\\)、\\(|E|\\) 当自变量。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>等差、等比、调和和给出后课最常用的阶。</li><li>\\(T(n)=T(n-1)+f(n)\\) 展开为 \\(f\\) 的和。</li><li>记号上一课已有；本课给 \\(T(n)\\) 从哪来。图是下一课的对象。</li><li>出处：Rosen；CLRS。</li></ul>',7))])}const C=s(d,[["render",p]]);export{B as __pageData,C as default};
